12	class UserRepositoryImpl internal constructor(
13	    private val apiClient: GorestApiClient,
14	) : UserRepository {
15	    override suspend fun getUsers(page: Int, perPage: Int): AppResult<Page<User>> = repositoryCall {
16	        val response = apiClient.getUsers(page = page, perPage = perPage)
17	        Page(
18	            items = response.items.map { it.toDomain() },
19	            page = response.page,
20	            perPage = response.perPage,
21	            totalPages = response.totalPages,
22	        )
23	    }
24	
25	    override suspend fun getUser(id: Long): AppResult<User> = repositoryCall {
26	        apiClient.getUser(id).toDomain()
27	    }
28	
29	    override suspend fun getUserPosts(userId: Long): AppResult<List<Post>> = repositoryCall {
30	        apiClient.getUserPosts(userId).map { it.toDomain() }
31	    }
32	
33	    override suspend fun getUserTodos(userId: Long): AppResult<List<Todo>> = repositoryCall {
34	        apiClient.getUserTodos(userId).map { it.toDomain() }
