 1	package com.sliide.useractivity.data.repository
 2	
 3	import com.sliide.useractivity.domain.AppError
 4	import com.sliide.useractivity.domain.AppResult
 5	import io.ktor.client.plugins.HttpRequestTimeoutException
 6	import io.ktor.client.plugins.ResponseException
 7	import io.ktor.http.HttpStatusCode
 8	import kotlinx.io.IOException
 9	import kotlinx.coroutines.CancellationException
10	
11	internal suspend fun <T> repositoryCall(block: suspend () -> T): AppResult<T> = try {
12	    AppResult.Success(block())
13	} catch (error: CancellationException) {
14	    throw error
15	} catch (error: ResponseException) {
16	    AppResult.Failure(error.toAppError())
17	} catch (error: HttpRequestTimeoutException) {
18	    AppResult.Failure(AppError.Timeout)
19	} catch (error: IOException) {
20	    AppResult.Failure(AppError.Network)
21	} catch (error: Throwable) {
22	    AppResult.Failure(AppError.Unknown(error.message))
23	}
24	
25	private fun ResponseException.toAppError(): AppError = when (val status = response.status) {
26	    HttpStatusCode.Unauthorized,
27	    HttpStatusCode.Forbidden,
28	    -> AppError.Unauthorized
29	
30	    HttpStatusCode.NotFound -> AppError.NotFound
31	    HttpStatusCode.UnprocessableEntity -> AppError.Validation(message)
32	    else -> if (status.value >= 500) {
33	        AppError.Server(status.value)
34	    } else {
35	        AppError.Unknown("HTTP ${status.value}")
36	    }
37	}

