20	@Composable
21	fun AppRoot(databaseDriverFactory: DatabaseDriverFactory) {
22	    val navigator = remember { AppNavigator() }
23	    val scope = rememberCoroutineScope()
24	    val koinApplication = remember(databaseDriverFactory) {
25	        koinApplication {
26	            modules(appModule(databaseDriverFactory))
27	        }
28	    }
29	    val koin = koinApplication.koin
30	    val userFeedViewModel = remember(scope, koinApplication) {
31	        koin.get<UserFeedViewModel> { parametersOf(scope) }
32	    }
33	    val userFeedState by userFeedViewModel.state.collectAsState()
34	
35	    LaunchedEffect(userFeedViewModel) {
36	        userFeedViewModel.load()
37	    }
38	    DisposableEffect(koinApplication) {
39	        onDispose {
40	            koin.get<HttpClient>().close()
41	            koin.get<SqlDriver>().close()
42	            koinApplication.close()
43	        }
44	    }
45	
46	    BoxWithConstraints {
47	        when (appLayoutClassForWidth(maxWidth)) {
48	            AppLayoutClass.Compact -> CompactAppShell(
49	                navigator = navigator,
50	                userFeedState = userFeedState,
51	                onUserFeedRefresh = userFeedViewModel::refresh,
52	                onUserFeedRetry = userFeedViewModel::retry,
53	                onAddUserClick = {},
54	            )
55	            AppLayoutClass.Expanded -> ExpandedAppShell(
56	                navigator = navigator,
57	                availableWidth = maxWidth,
58	                userFeedState = userFeedState,
59	                onUserFeedRefresh = userFeedViewModel::refresh,
60	                onUserFeedRetry = userFeedViewModel::retry,
61	                onAddUserClick = {},
62	            )
63	        }
64	    }
65	}

